#!/usr/bin/env node
/*
 * fetch-site-fonts.mjs — writes an embedded fonts.css for each site in sites/.
 *
 * Same idea as tools/fetch-fonts.js, which does this for the FitAI app, with
 * one difference that matters: each site gets its own file holding only its own
 * families. A single shared fonts.css across three sites would push half a
 * megabyte of base64 at a visitor who is only looking at one of them, and the
 * three sites deliberately share no type — the typeface is most of what makes
 * a horror house not read like a law firm.
 *
 * The generated files are committed, so no site ever needs the network. Rerun
 * this only when a font stack changes.
 *
 * Usage: node tools/fetch-site-fonts.mjs [site ...]
 */

import { writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

/* Each site's stack: a display face that carries the brand, a body face that
 * has to stay readable at 16px for a paragraph, and — where the design counts
 * things out loud — a mono for digits. Every Hebrew family here ships a real
 * hebrew subset; IBM Plex Mono has no Hebrew and is only ever used for numbers
 * and Latin codes, which is why it is asked for latin alone. */
const SITES = {
  horror: {
    families: [
      'Karantina:wght@400;700',   // display — condensed, brutal, faintly wrong
      'Rubik:wght@400;500;700',   // body
      'IBM+Plex+Mono:wght@400;600',
    ],
    note: 'Karantina (display), Rubik (body), IBM Plex Mono (case-file numbers)',
  },
  escape: {
    families: [
      'Frank+Ruhl+Libre:wght@500;700;900',  // display — a Hebrew serif, bookish
      'Assistant:wght@400;600;700',         // body
      'IBM+Plex+Mono:wght@400;600',         // locks, codes, the clock
    ],
    note: 'Frank Ruhl Libre (display), Assistant (body), IBM Plex Mono (codes and clock)',
  },
  lawyer: {
    families: [
      'Noto+Serif+Hebrew:wght@500;600;700', // display — authority, set in a serif
      'Heebo:wght@400;500;700',             // body
    ],
    note: 'Noto Serif Hebrew (display), Heebo (body)',
  },
};

// A modern desktop UA is what makes Google serve woff2 rather than ttf.
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';

const KEEP_SUBSETS = new Set(['hebrew', 'latin']);

async function get(url, asBuffer) {
  const res = await fetch(url, { headers: { 'User-Agent': UA } });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} for ${url}`);
  return asBuffer ? Buffer.from(await res.arrayBuffer()) : res.text();
}

async function build(site, spec) {
  const cssUrl = 'https://fonts.googleapis.com/css2?'
    + spec.families.map((f) => `family=${f}`).join('&')
    + '&display=swap';

  const css = await get(cssUrl, false);

  // Google's CSS emits a /* subset */ comment before each @font-face block.
  const blocks = [...css.matchAll(/\/\*\s*([^*]+?)\s*\*\/\s*(@font-face\s*\{[\s\S]*?\})/g)];
  if (!blocks.length) throw new Error(`could not parse any @font-face blocks for ${site}`);

  const out = [
    `/* fonts.css — GENERATED by tools/fetch-site-fonts.mjs. Do not edit by hand.`,
    ` *`,
    ` * Hebrew and Latin subsets of ${spec.note},`,
    ` * embedded as base64 so the site renders identically offline.`,
    ` * Regenerate with: node tools/fetch-site-fonts.mjs ${site}`,
    ` *`,
    ` * Fonts are licensed under the SIL Open Font License 1.1.`,
    ` */`,
    '',
  ];

  let kept = 0;
  let bytes = 0;

  for (const [, subset, block] of blocks) {
    if (!KEEP_SUBSETS.has(subset.trim())) continue;
    const url = /url\((https:\/\/[^)]+)\)/.exec(block);
    if (!url) continue;

    const buf = await get(url[1], true);
    bytes += buf.length;
    kept++;

    const family = /font-family:\s*'([^']+)'/.exec(block);
    const weight = /font-weight:\s*([^;]+);/.exec(block);
    const style = /font-style:\s*([^;]+);/.exec(block);
    const range = /unicode-range:\s*([^;]+);/.exec(block);

    out.push('@font-face {');
    out.push(`  font-family: '${family ? family[1] : 'unknown'}';`);
    out.push(`  font-style: ${style ? style[1].trim() : 'normal'};`);
    out.push(`  font-weight: ${weight ? weight[1].trim() : '400'};`);
    out.push('  font-display: swap;');
    out.push(`  src: url(data:font/woff2;base64,${buf.toString('base64')}) format('woff2');`);
    if (range) out.push(`  unicode-range: ${range[1].trim()};`);
    out.push('}');
    out.push('');
  }

  const dest = resolve(ROOT, `sites/${site}/styles/fonts.css`);
  writeFileSync(dest, out.join('\n'));
  console.log(`sites/${site}/styles/fonts.css — ${kept} faces, ${Math.round(bytes / 1024)} KB of font data`);
}

const wanted = process.argv.slice(2).filter((a) => !a.startsWith('-'));
const list = wanted.length ? wanted : Object.keys(SITES);

for (const site of list) {
  const spec = SITES[site];
  if (!spec) throw new Error(`unknown site "${site}" — known: ${Object.keys(SITES).join(', ')}`);
  await build(site, spec);
}
